std::uint64_t bits(double v){std::uint64_t b;std::memcpy(&b,&v,sizeof b);return b;}
std::vector<std::uint64_t>fingerprint(const Dataset&d){std::vector<std::uint64_t>b;auto s=d.shape();for(int t=0;t<s.t;++t)for(int c=0;c<s.c;++c)for(int z=0;z<s.z;++z)for(double v:d.plane({t,c,z})->pixels)b.push_back(bits(v));return b;}
Dataset formula(PixelType type=PixelType::UInt8,int channels=3,int offset=0,int width=5){Stack planes;for(int t=0;t<2;++t)for(int c=0;c<channels;++c)for(int z=0;z<4;++z){Image p(width,3,1,type);for(int y=0;y<3;++y)for(int x=0;x<width;++x)p.at(x,y)=offset+40*t+30*c+5*z+2*y+x;planes.push_back(std::move(p));}SpatialCalibration cal;cal.spacing={.5,1.25,2.5};cal.origin={11,-7,19};cal.unit="um";cal.frame_interval=.75;cal.time_origin=2.25;return Dataset::from_planes({2,channels,4,3,width,1},std::move(planes),cal);}
ChannelDisplayState state(ChannelDisplayProjection p=ChannelDisplayProjection::Sum,int count=3,bool v2=true){ChannelDisplayState s;s.version=v2?ChannelDisplayVersion::V2:ChannelDisplayVersion::V1;s.projection=p;for(int c=0;c<count;++c){ChannelDisplayChannel ch;ch.lut.name=c%3==0?"Red":c%3==1?"Green":"Blue";s.channels.push_back(ch);}return s;}
ChannelDisplayState constants(int count=3){auto s=state(ChannelDisplayProjection::Sum,count,false);const std::array<std::array<std::uint8_t,3>,3>palette{{{200,30,90},{80,150,60},{120,70,220}}};for(int c=0;c<count;++c){ChannelDisplayTable table{};table.fill(palette[c%3]);s.channels[c].lut.name.clear();s.channels[c].lut.table=table;}return s;}
ChannelDisplayRequest setting(ChannelDisplayProjection p=ChannelDisplayProjection::Sum,bool v2=true,int count=3){return {ChannelDisplayAction::Set,state(p,count,v2),{}};}
ChannelDisplayRequest select_max(){return {ChannelDisplayAction::SelectMax,{},{}};}
void position(Document&d,int t,int c,int z){auto v=d.snapshot().display();v.t=t;v.c=c;v.crosshair={2,1,z};v.zoom=2.5;v.planeZoom={1.5,2.5,3.5};v.pan={{{1,2},{3,4},{5,6}}};v.orthogonal=true;v.linkedZoom=false;v.properties["unrelated"]=metadata_array({true,7,std::string("retained")});d.set_display(v);}
