bool same_display(const DisplayState&a,const DisplayState&b){return a.t==b.t&&a.c==b.c&&a.crosshair==b.crosshair&&a.orthogonal==b.orthogonal&&a.linkedZoom==b.linkedZoom&&a.zoom==b.zoom&&a.planeZoom==b.planeZoom&&a.pan==b.pan&&a.revision==b.revision&&metadata_equal(a.properties,b.properties);}
