int main(int argc,char**argv){try{if(argc>2)throw std::invalid_argument("Usage: command_v2 [records|resolve|replay|rebind|limits|all]");std::string group=argc==2?argv[1]:"all";if(group!="all"&&group!="records"&&group!="resolve"&&group!="replay"&&group!="rebind"&&group!="limits")throw std::invalid_argument("Unknown V2 group");if(group=="all"||group=="records")records();if(group=="all"||group=="resolve")resolve();if(group=="all"||group=="replay")replay();if(group=="all"||group=="rebind")rebind();if(group=="all"||group=="limits")limits();const std::size_t expected_cases=group=="all"?29:group=="records"||group=="limits"?7:5;check(cases.size()==expected_cases,"Frozen named membership changed");auto sorted=cases;std::sort(sorted.begin(),sorted.end());check(std::adjacent_find(sorted.begin(),sorted.end())==sorted.end(),"Duplicate named case");std::cout<<"channel_display_command_v2 "<<group<<": "<<checks<<" checks; "<<cases.size()<<" named cases\n";for(const auto&n:cases)std::cout<<n<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"channel_display_command_v2 after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
